prologue:
/* A key counts as bound when the game has a cvar or a command on it */
static MOD_UNUSED int input_key_bound(int key) {
    AmodKeyInfo info;
    if (API->input == 0) return 0;
    memset(&info, 0, sizeof info);
    info.structSize = sizeof info;
    if (API->input->GetKey(SELF, key, &info) == 0) return 0;
    return info.bind != AMOD_KEY_UNBOUND;
}

/* The cursor lives in the 640x480 menu space, y counted from the top */
static MOD_UNUSED float input_cursor_x(void) {
    float x = 0.0f, y = 0.0f;
    if (API->input != 0) API->input->GetCursor(SELF, &x, &y);
    return x;
}

static MOD_UNUSED float input_cursor_y(void) {
    float x = 0.0f, y = 0.0f;
    if (API->input != 0) API->input->GetCursor(SELF, &x, &y);
    return y;
}

/* A command bound to a key keeps its parameters; this reads one of them */
static MOD_UNUSED const char* input_key_param(int key, int index) {
    return API->input != 0 ? API->input->GetKeyParam(SELF, key, index) : 0;
}

static MOD_UNUSED int input_key_count(void) {
    return API->input != 0 ? API->input->KeyCount(SELF) : 0;
}
